package com.notireader.app.data

import androidx.lifecycle.LiveData
import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query

@Dao
interface MessageDao {
    @Insert
    suspend fun insertMessage(message: MessageEntity)

    @Query("SELECT * FROM messages ORDER BY timestamp DESC")
    fun getAllMessages(): LiveData<List<MessageEntity>>

    @Query("UPDATE messages SET isDeleted = 1 WHERE id = :id")
    suspend fun markAsDeleted(id: Int)
}

package com.notireader.app.data

import androidx.lifecycle.LiveData
import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query

@Dao
interface MessageDao {
    @Insert
    suspend fun insertMessage(message: MessageEntity)

    @Query("SELECT * FROM messages ORDER BY timestamp DESC")
    fun getAllMessages(): LiveData<List<MessageEntity>>

    @Query("UPDATE messages SET isDeleted = 1 WHERE id = :id")
    suspend fun markAsDeleted(id: Int)

    @Query("UPDATE messages SET isDeleted = 1 WHERE sender = :sender AND message = :message AND timestamp = :timestamp")
    suspend fun markAsDeletedByDetails(sender: String, message: String, timestamp: Long)
}

package com.notireader.app.data.database

import androidx.lifecycle.LiveData
import androidx.room.Dao
import androidx.room.Insert
import androidx.room.Query

@Dao
interface MessageDao {
    @Insert
    suspend fun insertMessage(message: MessageEntity)

    @Query("SELECT * FROM messages ORDER BY timestamp DESC")
    fun getAllMessages(): LiveData<List<MessageEntity>>

    @Query("UPDATE messages SET isDeleted = 1 WHERE sender = :sender AND message = :message AND timestamp = :timestamp")
    suspend fun markAsDeletedByDetails(sender: String, message: String, timestamp: Long)

    @Query("SELECT * FROM messages WHERE sender = :sender ORDER BY timestamp DESC")
    fun getMessagesForSender(sender: String): LiveData<List<MessageEntity>>

    @Query("SELECT COUNT(*) FROM messages WHERE sender = :sender AND message = :message AND ABS(timestamp - :timestamp) < 10000")
    suspend fun countSimilarMessages(sender: String, message: String, timestamp: Long): Int

    @Query("SELECT * FROM messages WHERE sourcePackage = :sourcePackage ORDER BY timestamp DESC")
    fun getMessagesForPackage(sourcePackage: String): LiveData<List<MessageEntity>>
}

package com.notireader.app.data.database

import androidx.lifecycle.LiveData
import androidx.room.Dao
import androidx.room.Insert
import androidx.room.Query

@Dao
interface MessageDao {
    @Insert
    suspend fun insertMessage(message: MessageEntity)

    @Query("SELECT * FROM messages ORDER BY timestamp DESC")
    fun getAllMessages(): LiveData<List<MessageEntity>>

    @Query("UPDATE messages SET isDeleted = 1 WHERE sender = :sender AND message = :message AND timestamp = :timestamp")
    suspend fun markAsDeletedByDetails(sender: String, message: String, timestamp: Long)

    @Query("SELECT * FROM messages WHERE sender = :sender ORDER BY timestamp DESC")
    fun getMessagesForSender(sender: String): LiveData<List<MessageEntity>>

    @Query("SELECT COUNT(*) FROM messages WHERE sender = :sender AND message = :message AND ABS(timestamp - :timestamp) < 10000")
    suspend fun countSimilarMessages(sender: String, message: String, timestamp: Long): Int

    @Query("SELECT * FROM messages WHERE sourcePackage = :sourcePackage ORDER BY timestamp DESC")
    fun getMessagesForPackage(sourcePackage: String): LiveData<List<MessageEntity>>

    @Query("UPDATE messages SET isRead = 1 WHERE sender = :sender")
    suspend fun markMessagesAsRead(sender: String)

    @Query("SELECT COUNT(*) FROM messages WHERE sender = :sender AND isRead = 0")
    suspend fun countUnreadMessagesForSender(sender: String): Int
}

package com.notireader.app.data.repository

import android.util.Log
import androidx.lifecycle.LiveData
import androidx.lifecycle.map
import com.notireader.app.data.database.MessageDao
import com.notireader.app.data.mappers.toMessageEntity
import com.notireader.app.data.mappers.toMessageModel
import com.notireader.app.domain.models.MessageModel
import com.notireader.app.domain.repository.NotiRepository
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

class DefaultRepository(
    private val messageDao: MessageDao
) : NotiRepository {
    override fun getAllMessages(): LiveData<List<MessageModel>> {
        return messageDao.getAllMessages().map { messageEntities ->
            messageEntities.map { messageEntity ->
                messageEntity.toMessageModel()
            }
        }
    }

    override suspend fun countUnreadMessages(): Int {
        // Not used for a specific sender, so return total unread count
        return messageDao.getAllMessages().value?.count { !it.isRead } ?: 0
    }

    override suspend fun countUnreadMessagesForSender(sender: String): Int {
        return messageDao.countUnreadMessagesForSender(sender)
    }

    override suspend fun markMessageAsRead(sender: String, message: String, timestamp: Long) {
        // Mark all messages for sender as read
        messageDao.markMessagesAsRead(sender)
    }

    override suspend fun insertMessage(message: MessageModel) {
        withContext(Dispatchers.IO) {
            messageDao.insertMessage(message.toMessageEntity())
        }
    }

    override suspend fun markMessageAsDeletedByDetails(sender: String, message: String, timestamp: Long) {
        withContext(Dispatchers.IO) {
            messageDao.markAsDeletedByDetails(sender, message, timestamp)
        }
    }

    override suspend fun onWhatsAppNotificationReceived(message: MessageModel) {
        Log.d("xyz", "onWhatsAppNotificationReceived: $message")
        val count = messageDao.countSimilarMessages(message.sender, message.message, message.timestamp)
        if (count == 0) {
            insertMessage(message)
        } else {
            Log.d("xyz", "Duplicate message detected, skipping insert: $message")
        }
    }

    override fun getMessagesForSender(sender: String): LiveData<List<MessageModel>> {
        return messageDao.getMessagesForSender(sender).map { messageEntities ->
            messageEntities.map { it.toMessageModel() }
        }
    }

    override fun getMessagesForPackage(sourcePackage: String): LiveData<List<MessageModel>> {
        return messageDao.getMessagesForPackage(sourcePackage).map { messageEntities ->
            messageEntities.map { it.toMessageModel() }
        }
    }

    override suspend fun isDuplicateMessage(sender: String, message: String, timestamp: Long): Boolean {
        return withContext(Dispatchers.IO) {
            messageDao.countSimilarMessages(sender, message, timestamp) > 0
        }
    }
}

